exempt = (input('exempt_assets') || {})['CKV_AWS_266'] || []

control 'CKV_AWS_266' do
  title 'Ensure DB Snapshot copy uses CMK'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_db_snapshot_copy resources that actually exist, read through the
    stock inspec-aws aws_rds_snapshot resource.
  DESC

  desc 'rationale', <<~RATIONALE
    A snapshot copy is a second, independently retained image of the
    database. Encrypting it under a managed key keeps the ability to revoke
    access to the copy without deleting it, which is the only lever
    available once a snapshot has been shared or moved to another region.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_db_snapshot_copy: kms_key_id is CKV_ANY
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_db_snapshot_copy:

      resource "aws_db_snapshot_copy" "app" {
        source_db_snapshot_identifier = aws_db_snapshot.app.db_snapshot_arn
        target_db_snapshot_identifier = "app-db-2026-08-30-copy"
        kms_key_id                    = aws_kms_key.rds.arn
      }

    Out of band — aws_db_snapshot_copy:

      aws rds copy-db-snapshot --source-db-snapshot-identifier app-db-2026-08-30 --target-db-snapshot-identifier app-db-2026-08-30-copy --kms-key-id <key-arn>

    Note (aws_db_snapshot_copy): An existing unencrypted snapshot cannot be
    encrypted in place. Copy it with --kms-key-id and delete the unencrypted
    original.
  FIX

  tag checkov_id:            'CKV_AWS_266'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
